":"cr:Field","@id":"images/sex","name":"sex","description":"Sex as recorded by the source: F or M.","dataType":"sc:Text","source":{"fileObject":{"@id":"75e8db79-006f-5710-a266-8c041dde3a42"},"extract":{"column":"sex"}}},{"@type":"cr:Field","@id":"images/age_band","name":"age_band","description":"Age at the examination, as a band: 18-39, 40-59 or 60+.","dataType":"sc:Text","source":{"fileObject":{"@id":"75e8db79-006f-5710-a266-8c041dde3a42"},"extract":{"column":"age_band"}}}]}],"bio:imagingModality":[{"@type":"sc:DefinedTerm","name":"X-ray"}],"bio:bodyRegion":[{"@type":"sc:DefinedTerm","name":"Chest"}],"bio:anonymizationLevel":"DEIDENTIFIED","bio:synthetic":true,"rai:dataCollection":"Selection rule: 200 images drawn with a fixed seed (20261217) from the images of the metadata file that have a reference label, a patient aged 18 or over, sex recorded as F or M and a PA projection. Six strata (sex by age band: 18-39, 40-59, 60+) of equal size to within one image, 40% of each with the finding; at most one image per patient. 60 of them, with the same balance, form the reading subset.","rai:dataCollectionTimeframe":"Slice prepared on 2026-11-20","rai:dataAnnotationProtocol":"The reference label (airspace opacity present or absent) is invented for the stand-in and has no relation to the placeholder images.","rai:personalSensitiveInformation":"Sex and age band are published per image. Age in years, the patient identifier and every other column of the source metadata are left out.","bio:labelProtocol":{"version":"Invented labels of the synthetic stand-in","labelScale":"0 = airspace opacity absent; 1 = present","gradersPerItem":1,"graderQualification":"none: generated by a script","perRaterLabelsRetained":false},"prov:wasDerivedFrom":{"@type":"prov:Entity","@id":"https://doi.org/10.1109/CVPR.2017.369","name":"NIH ChestX-ray14 (ChestX-ray8), Wang et al., 2017"},"prov:wasGeneratedBy":[{"@type":["prov:Activity","https://w3id.org/dpv/ai#DataCollection"],"@id":"#activity-workshop-slice-v1","name":"Selection of a 200-image slice of NIH ChestX-ray14, one image per patient, balanced by sex and age band, at most 1024 px on the longest side","prov:startedAtTime":"2026-11-20T00:00:00Z","prov:endedAtTime":"2026-11-20T00:00:00Z","prov:used":"https://doi.org/10.1109/CVPR.2017.369","prov:wasAssociatedWith":{"@type":"prov:SoftwareAgent","name":"oci-platform scripts/radiology-workshop","prov:actedOnBehalfOf":{"@type":"prov:Organization","name":"OCI Platform (GI-AI4H)"}}},{"@type":["prov:Activity","https://w3id.org/dpv/ai#DataLabelling"],"@id":"#activity-reference-labels","name":"Reference labels of the evaluation task (not published)","prov:used":{"@type":"prov:Entity","@id":"#guideline-reference-labels","name":"Invented labels of the synthetic stand-in","version":"1"},"prov:wasAssociatedWith":[{"@type":"prov:SoftwareAgent","prov:hadRole":"Annotator"}]}],"prov:wasAttributedTo":[{"@type":"prov:Organization","name":"National Institutes of Health Clinical Center (data provider)"},{"@type":"prov:Organization","name":"OCI Platform (GI-AI4H): re-publisher of the workshop slice"}],"odrl:hasOffer":{"@type":"odrl:Offer","@id":"#offer-source-terms","odrl:permission":[{"odrl:action":["odrl:use","odrl:distribute","odrl:derive"],"odrl:target":"nih-chestxray14-workshop","odrl:duty":[{"odrl:action":"odrl:attribute"}]}]},"cr:consentCode":[{"@type":"sc:DefinedTerm","@id":"http://purl.obolibrary.org/obo/DUO_0000004","termCode":"DUO_0000004","name":"no restriction","inDefinedTermSet":"http://purl.obolibrary.org/obo/duo.owl"}]}$manifest$::jsonb;
