-- ----------------------------------------------------------------------------
-- 2. Evaluation task with the HIDDEN reference labels.
-- One binary finding, as a CLASSIFICATION task with two classes: 0 for
-- absent, 1 for present (decided 2026-11-22). Its result page shows the
-- per-class table: the recall of class 1 is the sensitivity, the recall of
-- class 0 the specificity. The referable threshold is not read by this kind;
-- it is set to 1 so the row stays meaningful if the kind is ever changed.
-- Same rule as the answer key of demo.sql (#464): inserted once, never
-- overwritten, and the seed fails if the stored key differs from this file.
-- The error names item ids only, never a label: migrate logs are printed in
-- the deploy output.
-- ----------------------------------------------------------------------------

DO $workshop_answer_key$
DECLARE
  expected_gt CONSTANT jsonb := '{"standin_00002_001":1,"standin_00005_001":1,"standin_00012_002":1,"standin_00014_000":0,"standin_00015_001":1,"standin_00019_000":0,"standin_00022_000":1,"standin_00027_000":0,"standin_00032_000":0,"standin_00041_001":0,"standin_00044_001":0,"standin_00056_000":0,"standin_00061_000":0,"standin_00072_002":0,"standin_00073_000":1,"standin_00076_000":0,"standin_00109_001":0,"standin_00119_000":1,"standin_00120_001":1,"standin_00125_002":0,"standin_00126_000":0,"standin_00127_002":0,"standin_00128_002":1,"standin_00133_001":0,"standin_00136_002":1,"standin_00139_001":1,"standin_00148_000":0,"standin_00160_001":0,"standin_00180_000":1,"standin_00192_001":1,"standin_00195_001":0,"standin_00216_001":1,"standin_00219_002":0,"standin_00227_002":1,"standin_00229_000":1,"standin_00247_002":0,"standin_00251_001":0,"standin_00253_001":0,"standin_00268_000":0,"standin_00278_001":0,"standin_00283_001":0,"standin_00296_001":0,"standin_00308_000":0,"standin_00311_001":0,"standin_00318_000":1,"standin_00325_001":1,"standin_00326_001":0,"standin_00340_002":0,"standin_00343_000":0,"standin_00355_000":0,"standin_00367_000":0,"standin_00369_001":1,"standin_00370_001":1,"standin_00373_001":1,"standin_00379_001":1,"standin_00381_001":0,"standin_00394_001":1,"standin_00399_001":0,"standin_00400_000":0,"standin_00408_000":0,"standin_00417_001":0,"standin_00421_001":1,"standin_00432_001":1,"standin_00455_000":0,"standin_00457_000":1,"standin_00480_001":1,"standin_00495_001":0,"standin_00500_001":0,"standin_00501_001":0,"standin_00502_000":0,"standin_00509_000":0,"standin_00522_000":1,"standin_00535_000":0,"standin_00542_001":0,"standin_00555_000":0,"standin_00556_001":1,"standin_00568_000":0,"standin_00578_000":1,"standin_00581_002":0,"standin_00583_000":0,"standin_00596_000":1,"standin_00608_000":1,"standin_00612_001":1,"standin_00614_000":1,"standin_00622_001":1,"standin_00627_000":1,"standin_00632_000":0,"standin_00638_000":0,"standin_00641_000":0,"standin_00650_000":1,"standin_00669_002":0,"standin_00672_000":0,"standin_00676_000":0,"standin_00678_000":1,"standin_00682_000":1,"standin_00692_000":0,"standin_00693_001":0,"standin_00705_000":0,"standin_00717_000":1,"standin_00732_001":1,"standin_00738_002":0,"standin_00741_001":0,"standin_00758_002":0,"standin_00768_000":0,"standin_00775_001":1,"standin_00777_002":0,"standin_00778_001":1,"standin_00779_001":1,"standin_00780_001":1,"standin_00802_001":1,"standin_00816_001":0,"standin_00826_002":0,"standin_00827_002":1,"standin_00828_000":0,"standin_00832_001":1,"standin_00838_001":1,"standin_00843_000":0,"standin_00845_000":0,"standin_00853_002":1,"standin_00856_001":1,"standin_00873_002":0,"standin_00876_001":0,"standin_00901_000":0,"standin_00903_002":0,"standin_00910_001":0,"standin_00912_000":0,"standin_00914_000":0,"standin_00919_002":1,"standin_00921_000":1,"standin_00925_000":1,"standin_00928_001":1,"standin_00937_001":0,"standin_00944_001":0,"standin_00949_000":1,"standin_00965_000":0,"standin_00967_000":0,"standin_00991_000":0,"standin_00998_001":0,"standin_00999_000":1,"standin_01008_001":1,"standin_01014_001":0,"standin_01015_002":0,"standin_01019_001":1,"standin_01020_000":0,"standin_01030_000":0,"standin_01031_001":1,"standin_01032_001":0,"standin_01034_000":0,"standin_01042_000":1,"standin_01045_000":0,"standin_01050_000":0,"standin_01056_001":0,"standin_01058_001":1,"standin_01065_001":1,"standin_01076_002":0,"standin_01087_000":0,"standin_01090_000":1,"standin_01105_001":0,"standin_01109_001":0,"standin_01123_000":0,"standin_01125_002":0,"standin_01130_000":0,"standin_01137_001":1,"standin_01144_002":0,"standin_01145_000":1,"standin_01146_000":0,"standin_01149_001":0,"standin_01153_000":0,"standin_01155_000":1,"standin_01160_001":0,"standin_01163_000":0,"standin_01167_000":0,"standin_01189_000":0,"standin_01219_002":1,"standin_01221_000":1,"standin_01227_000":1,"standin_01228_002":0,"standin_01238_000":0,"standin_01239_002":1,"standin_01252_000":0,"standin_01256_000":0,"standin_01263_002":1,"standin_01270_001":1,"standin_01284_000":1,"standin_01302_000":1,"standin_01311_002":0,"standin_01322_000":0,"standin_01326_001":1,"standin_01336_000":0,"standin_01338_000":1,"standin_01344_001":0,"standin_01349_001":0,"standin_01350_000":1,"standin_01353_001":1,"standin_01371_002":0,"standin_01372_001":1,"standin_01379_001":0,"standin_01383_000":0,"standin_01386_000":0,"standin_01396_001":0}'::jsonb;
  stored_gt jsonb;
  drifted_ids text;
BEGIN
  INSERT INTO "evaluation"."evaluation_tasks"
      (id, slug, name, dataset_slug, task_kind, num_classes, referable_threshold,
       ground_truth, created_at, updated_at)
  VALUES (
      'd307fd8a-81ad-5133-8c89-d9df2b23ef61'::uuid,
      'nih-chestxray14-finding',
      'NIH ChestX-ray14 slice: airspace opacity, 0 = absent, 1 = present (synthetic stand-in)',
      'nih-chestxray14-workshop',
      'CLASSIFICATION'::"evaluation"."EvaluationTaskKind",
      2,
      1,
      expected_gt,
      CURRENT_TIMESTAMP,
      CURRENT_TIMESTAMP
  )
  ON CONFLICT (slug) DO NOTHING;

  SELECT ground_truth INTO stored_gt
  FROM "evaluation"."evaluation_tasks"
  WHERE slug = 'nih-chestxray14-finding';

  IF stored_gt IS DISTINCT FROM expected_gt THEN
    IF jsonb_typeof(stored_gt) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'evaluation task %: stored ground_truth is not a JSON object (got %), expected the answer key of the radiology-workshop seed profile',
        'nih-chestxray14-finding', coalesce(jsonb_typeof(stored_gt), 'NULL');
    END IF;

    SELECT string_agg(item_id, ', ' ORDER BY item_id) INTO drifted_ids
    FROM (
      SELECT coalesce(s.key, e.key) AS item_id
      FROM jsonb_each(stored_gt) AS s
      FULL OUTER JOIN jsonb_each(expected_gt) AS e ON s.key = e.key
      WHERE s.value IS DISTINCT FROM e.value
    ) AS diff;

    RAISE EXCEPTION 'evaluation task %: stored ground_truth differs from the radiology-workshop seed profile for item ids [%]. Not overwriting; see #464.',
      'nih-chestxray14-finding', drifted_ids;
  END IF;
END $workshop_answer_key$;

-- ----------------------------------------------------------------------------
-- 3. Annotation campaign: the reading exercise.
-- READY, not RUNNING: its tasks are created from the dataset's files by a
-- campaign manager once that exists (#646), and READY is the state in which
-- tasks can be loaded before the campaign is started. NO TASK IS CREATED
-- HERE. The 60 images of the reading subset are the ones flagged
-- `"campaign": true` in selection.json.
-- taskTimeoutHours is 1: an image left open returns to the queue within the
-- session (decision of 17 November 2026 on #644).
-- ----------------------------------------------------------------------------

INSERT INTO "annotation"."annotation_campaigns"
    (id, slug, name, description, status, task_kind, dataset_id, manifest_version_id,
     tool_integration_id, output_license, workflow_config, created_by_id,
     created_at, updated_at, started_at, completed_at)
SELECT
    'a3bd7644-16fe-5dbf-952d-bc818dd7c3be'::uuid,
    'nih-chestxray14-reading',
    'Lecture de radiographies thoraciques : Opacité alvéolaire',
    'Synthetic stand-in images, not diagnostic. Reading exercise of the December 2026 radiology workshop: 60 of the 200 images, one finding (airspace opacity) marked present or absent, 3 independent readers per image, arbitration on disagreement. Instructions are in French.',
    'READY'::"annotation"."CampaignStatus",
    'CLASSIFICATION'::"annotation"."CampaignTaskKind",
    ds.id,
    ver.id,
    tool.id,
    'CC-BY-4.0'::"annotation"."CampaignOutputLicense",
    '{"nAnnotators":3,"taskTimeoutHours":1}'::jsonb,
    '00000000-0000-4000-8000-000000000099',
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, NULL, NULL
FROM "catalog"."datasets" ds
JOIN "catalog"."dataset_versions" ver
  ON ver.dataset_id = ds.id AND ver.version = '1.0.0',
     "annotation"."annotation_tool_integrations" tool
WHERE ds.slug = 'nih-chestxray14-workshop'
  AND tool.slug = 'ohif-viewer'
ON CONFLICT (slug) DO NOTHING;

-- Instructions, in French. The version is the one the API would compute for
-- this text (first 16 hex characters of its sha256).
INSERT INTO "annotation"."annotation_campaign_instructions"
    (campaign_id, version, markdown_body, media_urls, created_by_id)
SELECT c.id, 'e4e2899efdbeaa45', $instructions$# Lecture de radiographies thoraciques : Opacité alvéolaire

> Images de substitution synthétiques, sans valeur diagnostique. Elles seront remplacées par les radiographies réelles.

## Objectif

Pour chaque radiographie thoracique de face, indiquer si le signe suivant est présent : **Opacité alvéolaire**.

## Ce que vous voyez

- Une seule image par tâche, sans renseignement clinique, sans âge ni sexe : la lecture se fait à l’aveugle.
- Chaque image est lue par 3 lecteurs, indépendamment. Vous ne voyez pas les réponses des autres lecteurs.

## Réponse attendue

- `present` : le signe est visible sur l’image.
- `absent` : le signe n’est pas visible sur l’image.

En cas de doute, choisissez la réponse qui vous paraît la plus probable et expliquez votre hésitation dans le commentaire.

## En cas de désaccord

Si les lectures ne concordent pas, l’image est transmise à un arbitre. Il voit l’image et les réponses, sans connaître leurs auteurs, et tranche en donnant sa raison.

## Délai

Une image ouverte et laissée sans réponse pendant 1 heure retourne dans la file d’attente et sera proposée à un autre lecteur.

## Rappel

Les images proviennent d’un jeu de données public, anonymisé par sa source, et sont utilisées ici pour la formation. Les réponses ne servent à aucune décision clinique.
$instructions$, '[]'::jsonb, '00000000-0000-4000-8000-000000000099'
FROM "annotation"."annotation_campaigns" c
WHERE c.slug = 'nih-chestxray14-reading'
ON CONFLICT (campaign_id, version) DO NOTHING;

-- Point the campaign at them, unless a manager has published their own since:
-- only an empty pointer or one that still names a version this seed wrote is
-- moved.
UPDATE "annotation"."annotation_campaigns" c
SET current_instructions_version = 'e4e2899efdbeaa45', updated_at = CURRENT_TIMESTAMP
WHERE c.slug = 'nih-chestxray14-reading'
  AND c.current_instructions_version IS DISTINCT FROM 'e4e2899efdbeaa45'
  AND (
    c.current_instructions_version IS NULL
    OR EXISTS (
      SELECT 1 FROM "annotation"."annotation_campaign_instructions" i
      WHERE i.campaign_id = c.id
        AND i.version = c.current_instructions_version
        AND i.created_by_id = '00000000-0000-4000-8000-000000000099'
    )
  );

